// Get ALL items from the previous node
const allItems = $input.all();

// Get the original text from Strip Boilerplate node
const stripBoilerplateText = $('Strip Boilerplate').first().json.text;

// Helper function to clean JSON strings
function cleanJSON(str) {
  if (!str) return null;
  if (typeof str === 'object') return str;

  return str
    .replace(/^```json\s*/i, '')
    .replace(/\s*```$/, '')
    .replace(/^"""/g, '')
    .replace(/"""$/g, '')
    .replace(/\r?\n/g, ' ')
    .trim();
}

// Get ALL synthesized throughlines and merge them
const synthesisItems = $("Synthesize Throughlines").all();
const allThroughLines = [];
const allCallouts = [];
const titles = [];

for (const item of synthesisItems) {
  try {
    // Handle both possible key names
    const rawText = item.json.text || item.json['through-line'];
    if (!rawText) continue;

    const parsed = JSON.parse(cleanJSON(rawText));
    // Skip error responses
    if (parsed.error) continue;
    if (parsed.title) titles.push(parsed.title);
    if (parsed.through_lines && Array.isArray(parsed.through_lines)) {
      allThroughLines.push(...parsed.through_lines);
    }
    if (parsed.callouts && Array.isArray(parsed.callouts)) {
        allCallouts.push(...parsed.callouts);
      }
  } catch (e) {
    // Skip unparseable items
    continue;
  }
}

// Use first title, or combine if meaningfully different
const documentTitle = titles[0] || 'Untitled Analysis';

// Deduplicate through-lines by lead (in case of overlap)
const seenLeads = new Set();
const uniqueThroughLines = allThroughLines.filter(tl => {
  if (seenLeads.has(tl.lead)) return false;
  seenLeads.add(tl.lead);
  return true;
});

// Deduplicate callouts by text
  const seenCalloutText = new Set();
  const uniqueCallouts = allCallouts.filter(c => {
    const normalized = c.text.toLowerCase().trim();
    if (seenCalloutText.has(normalized)) return false;
    seenCalloutText.add(normalized);
    return true;
  });

// ESCAPE the text for SQL - remove or escape problematic characters
const escapedText = stripBoilerplateText
  .replace(/\\/g, '\\\\')
  .replace(/'/g, "''")
  .replace(/"/g, '\\"')
  .replace(/\0/g, '\\0')
  .replace(/\n/g, '\\n')
  .replace(/\r/g, '\\r')
  .replace(/\t/g, '\\t');

// Find items with parsed data - check both possible key names
const metadataItem = allItems.find(item => {
  const content = item.json.metadata || item.json.text;
  return content && typeof content === 'string' && content.includes('"source"');
});

const themesItem = allItems.find(item => item.json.themes);
const tradesItem = allItems.find(item => item.json.trades);

// Validate required items exist
if (!metadataItem) {
  throw new Error('Metadata item not found in input. Available keys: ' + 
    allItems.map(i => Object.keys(i.json).join(',')).join(' | '));
}
if (!themesItem) {
  throw new Error('Themes item not found in input');
}
if (!tradesItem) {
  throw new Error('Trades item not found in input');
}

// Parse the data
let metadata, themes, trades;

try {
  const metadataRaw = metadataItem.json.metadata || metadataItem.json.text;
  metadata = JSON.parse(cleanJSON(metadataRaw));
} catch (e) {
  throw new Error(`Failed to parse metadata: ${e.message}`);
}

try {
  themes = JSON.parse(cleanJSON(themesItem.json.themes));
} catch (e) {
  throw new Error(`Failed to parse themes: ${e.message}`);
}

try {
  trades = JSON.parse(cleanJSON(tradesItem.json.trades));
} catch (e) {
  throw new Error(`Failed to parse trades: ${e.message}`);
}

// Create a document narrative summary
const documentNarrative = `Analysis of ${metadata.source || 'Unknown'} (${metadata.area || 'N/A'}) - ${themes.length} themes and ${trades.length} trade ideas extracted.`;

// Assemble the parsed_data JSONB object
const parsedData = {
  metadata: metadata,
  themes: themes,
  trades: trades,
  through_lines: uniqueThroughLines,
  callouts: uniqueCallouts,
  full_text: stripBoilerplateText,
  extraction_stats: {
    num_themes: themes.length,
    num_trades: trades.length,
    num_through_lines: uniqueThroughLines.length,
    num_callouts: uniqueCallouts.length,
    num_synthesis_blocks: synthesisItems.length,
    extraction_method: "LLM-based extraction"
  }
};

// Output matching your table structure
const output = {
  document_title: documentTitle,
  document_narrative: documentNarrative,
  source: metadata.source || 'Unknown',
  source_date: (metadata.source_date && metadata.source_date !== 'null' && metadata.source_date !== 'undefined' && metadata.source_date !== '') 
    ? metadata.source_date 
    : new Date().toISOString().split('T')[0],
  parsed_data: parsedData,
  parsed_at: new Date().toISOString(),
  synthesized: false,
  synthesized_by: null
};

return { json: output };
